export default async function f(
  { body, templateId, folderId, acknowledge, resolution, confirmedCopyId },
  ctx,
) {
  const { submissionId, name, email, score } = body || {};
  if (!submissionId || !name || !email || !Number.isFinite(score) || !templateId || !folderId)
    throw Error("Configure submission and template");
  if (score <= 3)
    return {
      phase: "skip",
      key: "",
      fileId: templateId,
      name,
      copyName: name + "'s Certificate",
      recipient: email,
      templateId,
      parents: [folderId],
      requests: [],
    };
  const key = "certificate:" + submissionId;
  let s = await ctx.state.get(key);
  if (!s) {
    s = { status: "ready-copy", submissionId, name, email, score, templateId, folderId };
    await ctx.state.set(key, s);
  }
  for (const k of ["submissionId", "name", "email", "score", "templateId", "folderId"])
    if (s[k] !== { submissionId, name, email, score, templateId, folderId }[k])
      throw Error("Submission changed");
  if (s.status.startsWith("pending-")) {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending certificate write " + key + " " + s.status);
    const phase = s.status.slice(8);
    if (resolution === "absent") s.status = "ready-" + phase;
    else if (phase === "copy") {
      if (!confirmedCopyId) throw Error("Provide confirmed copy ID");
      s.fileId = confirmedCopyId;
      s.status = "ready-replace";
    } else if (phase === "replace") s.status = "ready-email";
    else if (phase === "email") s.status = "done";
    await ctx.state.set(key, s);
  }
  const phase = s.status.replace("ready-", "");
  if (["copy", "replace"].includes(phase)) {
    s.status = "pending-" + phase;
    await ctx.state.set(key, s);
  }
  return {
    phase,
    key,
    fileId: s.fileId || templateId,
    name,
    copyName: name + "'s Certificate",
    recipient: email,
    templateId,
    parents: [folderId],
    requests: [
      {
        replaceAllText: {
          containsText: { text: "[ NAME ]", matchCase: false },
          replaceText: name,
          pageObjectIds: ["p"],
        },
      },
    ],
  };
}

