async function f({ key, phase, fileId, actualId, messageId, replies }, ctx) {
  const s = await ctx.state.get(key);
  if (!s || s.status !== "pending-" + phase) throw Error("Unexpected certificate state");
  if (phase === "copy") {
    if (!actualId) throw Error("Unknown template copy");
    s.fileId = actualId;
    s.status = "ready-replace";
  } else if (phase === "replace") {
    if (
      !fileId ||
      actualId !== fileId ||
      !Number.isInteger(replies?.[0]?.replaceAllText?.occurrencesChanged) ||
      replies[0].replaceAllText.occurrencesChanged < 1
    )
      throw Error("Name placeholder not replaced");
    s.status = "ready-email";
  } else if (phase === "email") {
    if (!messageId) throw Error("Unknown certificate email");
    s.status = "done";
  } else throw Error("Invalid phase");
  await ctx.state.set(key, s);
  return { ok: true };
}

export default async function run(input, ctx) {
  return f({ ...input, phase: "copy" }, ctx);
}

