export default async function f(
  { key, fileId, actualFileId, mimeType, transitUrl, name, recipient },
  ctx,
) {
  if (
    fileId !== actualFileId ||
    mimeType !== "application/pdf" ||
    !/^https:\/\//.test(transitUrl || "")
  )
    throw Error("Invalid exported certificate");
  const s = await ctx.state.get(key);
  if (!s || s.status !== "ready-email" || s.fileId !== fileId)
    throw Error("Unexpected certificate state");
  await ctx.state.set(key, { ...s, status: "pending-email" });
  const r = await ctx.actions.call("gmail.send_email", {
    to: recipient,
    subject: "Your quiz certificate",
    body: "Congratulations on passing the quiz! Your certificate is attached.",
    isHtml: false,
    attachments: [
      { filename: name + " Certificate.pdf", mimeType: "application/pdf", fileUrl: transitUrl },
    ],
  });
  if (!r?.messageId) throw Error("Unknown certificate email");
  return { messageId: r.messageId };
}

